INSERT INTO `news` (`id`, `title`, `category`, `date`, `status`, `cover`, `excerpt`, `body`, `region`, `author`, `seq`) VALUES ('mszr28e3k1m2','{\"uz\":\"Parlament diplomatiyasi va jadal ijtimoiy rivojlanishni qoÔÇİllab-quvvatlash boÔÇİyicha xalqaro hamkorlik\",\"ru\":\"ºşº░ªÇº╗º░º╝ºÁº¢ªéªüº║º░ªÅ º┤º©º┐º╗º¥º╝º░ªéº©ªÅ º© º╝ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢º¥ºÁ ªüº¥ªéªÇªâº┤º¢º©ªçºÁªüªéº▓º¥ º▓ º┐º¥º┤º┤ºÁªÇºÂº║ªâ ªâªüº║º¥ªÇºÁº¢º¢º¥º│º¥ ªüº¥ªåº©º░º╗ªîº¢º¥º│º¥ ªÇº░ºÀº▓º©ªéº©ªÅ\",\"en\":\"Parliamentary diplomacy and international cooperation in support of accelerated social development\"}','Diplomatiya','2026-08-18','published','uploads/parlament-diplomatiyasi-va-jadal-ijtimoi_20260819_090551_92807726.jpg','{\"uz\":\"Sessiyaga Jahon iqtisodiyoti va diplomatiya universitetining oÔÇİquv ishlari boÔÇİyicha birinchi prorektori Akram Umarov moderatorlik qilmoqda.\",\"ru\":\"º£º¥º┤ºÁªÇº©ªÇªâºÁªé ªüºÁªüªüº©ªÄ ºÉº║ªÇº░º╝ ºúº╝º░ªÇº¥º▓, º┐ºÁªÇº▓ªïº╣ º┐ªÇº¥ªÇºÁº║ªéº¥ªÇ º┐º¥ ªâªçºÁº▒º¢º¥º╣ ªÇº░º▒º¥ªéºÁ ºúº¢º©º▓ºÁªÇªüº©ªéºÁªéº░ º╝º©ªÇº¥º▓º¥º╣ ªıº║º¥º¢º¥º╝º©º║º© º© º┤º©º┐º╗º¥º╝º░ªéº©º©.\",\"en\":\"The session is moderated by Akram Umarov, First Vice-Rector for Academic Affairs at the University of World Economy and Diplomacy.\"}','{\"uz\":\"Sessiya davomida<i>muhokama qilinmoqda<\\/i>Barqaror rivojlanish maqsadlariga erishishda parlamentlararo hamkorlikning roli, parlamentlarning BMT tizimi institutlari va xalqaro tashkilotlar bilan oÔÇİzaro hamkorligi, shuningdek, ijtimoiy tashabbuslarni amalga oshirish va aholi turmush sifatini oshirishda xalqaro hamkorlik istiqbollari masalalari.<br><br>Munozarada<i>ishtirok eting<\\/i> <b>Qahramon Allaberganov<\\/b>, Markaziy Osiyo xalqaro instituti kafedra mudiri,<b>Shaxlo Hamraxo\'jaeva<\\/b>, OÔÇİzbekiston Respublikasi Prezidenti huzuridagi Strategik va mintaqalararo tadqiqotlar instituti yetakchi ilmiy xodimi va<b>Ulug\'bek Xasanov<\\/b>, Jahon iqtisodiyoti va diplomatiya universitetining xalqaro aloqalar kafedrasi professori, ÔÇ£Politics, Law, EconomicsÔÇØ xalqaro jurnali bosh muharriri.\",\"ru\":\"ºÆ ªàº¥º┤ºÁ ªüºÁªüªüº©º© <i>º¥º▒ªüªâºÂº┤º░ªÄªéªüªÅ<\\/i> º▓º¥º┐ªÇº¥ªüªï ªÇº¥º╗º© º╝ºÁºÂº┐º░ªÇº╗º░º╝ºÁº¢ªéªüº║º¥º│º¥ ªüº¥ªéªÇªâº┤º¢º©ªçºÁªüªéº▓º░ º▓ º┤º¥ªüªéº©ºÂºÁº¢º©º© ºĞºÁº╗ºÁº╣ ªâªüªéº¥º╣ªçº©º▓º¥º│º¥ ªÇº░ºÀº▓º©ªéº©ªÅ, º▓ºÀº░º©º╝º¥º┤ºÁº╣ªüªéº▓º©ªÅ º┐º░ªÇº╗º░º╝ºÁº¢ªéº¥º▓ ªü ªâªçªÇºÁºÂº┤ºÁº¢º©ªÅº╝º© ªüº©ªüªéºÁº╝ªï ºŞºŞºØ º© º╝ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢ªïº╝º© º¥ªÇº│º░º¢º©ºÀº░ªåº©ªÅº╝º©, º░ ªéº░º║ºÂºÁ º┐ºÁªÇªüº┐ºÁº║ªéº©º▓ªï º╝ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢º¥º│º¥ ªüº¥ªéªÇªâº┤º¢º©ªçºÁªüªéº▓º░ º▓ ªÇºÁº░º╗º©ºÀº░ªåº©º© ªüº¥ªåº©º░º╗ªîº¢ªïªà º©º¢º©ªåº©º░ªéº©º▓ º© º┐º¥º▓ªïªêºÁº¢º©º© º║º░ªçºÁªüªéº▓º░ ºÂº©ºÀº¢º© º¢º░ªüºÁº╗ºÁº¢º©ªÅ.<br><br>ºÆ º¥º▒ªüªâºÂº┤ºÁº¢º©º© <i>º┐ªÇº©º¢º©º╝º░ªÄªé ªâªçº░ªüªéº©ºÁ<\\/i> <b>ºÜº░ªàªÇº░º╝º¥º¢ ºÉº╗º╗º░º▒ºÁªÇº│º░º¢º¥º▓<\\/b>, º¢º░ªçº░º╗ªîº¢º©º║ º¥ªéº┤ºÁº╗º░ º£ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢º¥º│º¥ º©º¢ªüªéº©ªéªâªéº░ ºĞºÁº¢ªéªÇº░º╗ªîº¢º¥º╣ ºÉºÀº©º©, <b>º¿º░ªàº╗º¥ ºÑº░º╝ªÇº░ªàº¥ºÂº░ºÁº▓º░<\\/b>, º▓ºÁº┤ªâªëº©º╣ º¢º░ªâªçº¢ªïº╣ ªüº¥ªéªÇªâº┤º¢º©º║ ºİº¢ªüªéº©ªéªâªéº░ ªüªéªÇº░ªéºÁº│º©ªçºÁªüº║º©ªà º© º╝ºÁºÂªÇºÁº│º©º¥º¢º░º╗ªîº¢ªïªà º©ªüªüº╗ºÁº┤º¥º▓º░º¢º©º╣ º┐ªÇº© ºşªÇºÁºÀº©º┤ºÁº¢ªéºÁ ºáºÁªüº┐ªâº▒º╗º©º║º© ºúºÀº▒ºÁº║º©ªüªéº░º¢, º© <b>ºúº╗ªâº│º▒ºÁº║ ºÑº░ªüº░º¢º¥º▓<\\/b>, º┐ªÇº¥ªäºÁªüªüº¥ªÇ º║º░ªäºÁº┤ªÇªï º╝ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢ªïªà º¥ªéº¢º¥ªêºÁº¢º©º╣ ºúº¢º©º▓ºÁªÇªüº©ªéºÁªéº░ º╝º©ªÇº¥º▓º¥º╣ ªıº║º¥º¢º¥º╝º©º║º© º© º┤º©º┐º╗º¥º╝º░ªéº©º©, º│º╗º░º▓º¢ªïº╣ ªÇºÁº┤º░º║ªéº¥ªÇ º╝ºÁºÂº┤ªâº¢º░ªÇº¥º┤º¢º¥º│º¥ ºÂªâªÇº¢º░º╗º░ ┬½ºşº¥º╗º©ªéº©º║º░, º┐ªÇº░º▓º¥, ªıº║º¥º¢º¥º╝º©º║º░┬╗.\",\"en\":\"During the session<i>are being discussed<\\/i>issues of the role of inter-parliamentary cooperation in achieving the Sustainable Development Goals, interaction of parliaments with institutions of the UN system and international organizations, as well as prospects for international cooperation in the implementation of social initiatives and improving the quality of life of the population.<br><br>In discussion<i>take part<\\/i> <b>Kakhramon Allaberganov<\\/b>, Head of Department, International Institute of Central Asia,<b>Shakhlo Hamrakhozhaeva<\\/b>, leading researcher at the Institute for Strategic and Interregional Studies under the President of the Republic of Uzbekistan, and<b>Ulugbek Khasanov<\\/b>, Professor of the Department of International Relations at the University of World Economy and Diplomacy, editor-in-chief of the international journal ÔÇ£Politics, Law, EconomicsÔÇØ.\"}','Markaziy Osiyo','Daria Gorelkina',38);
