('ms76ubo824z1','album','','{\"uz\":\"Dunyo\",\"ru\":\"º£º©ªÇ\",\"en\":\"World\"}','2026-07-30','[{\"url\":\"uploads\\/img_20260723_065506_21b6d8f8.jpg\",\"title\":{\"uz\":\"Ochilish marosimi\",\"ru\":\"ºĞºÁªÇºÁº╝º¥º¢º©ªÅ º¥ªéº║ªÇªïªéº©ªÅ\",\"en\":\"Opening ceremony\"}},{\"url\":\"uploads\\/img_20260723_065516_94b12a4f.jpg\",\"title\":{\"uz\":\"Umumiy majlis\",\"ru\":\"ºşº╗ºÁº¢º░ªÇº¢º¥ºÁ ºÀº░ªüºÁº┤º░º¢º©ºÁ\",\"en\":\"Plenary session\"}},{\"url\":\"uploads\\/img_20260723_065528_c2fdecf9.jpg\",\"title\":{\"uz\":\"Ekspertlar muhokamasi\",\"ru\":\"º¡º║ªüº┐ºÁªÇªéº¢º░ªÅ º┤º©ªüº║ªâªüªüº©ªÅ\",\"en\":\"Expert discussion\"}},{\"url\":\"uploads\\/img_20260723_065537_10ca45c1.jpg\",\"title\":{\"uz\":\"Ikki tomonlama uchrashuv\",\"ru\":\"ºöº▓ªâªüªéº¥ªÇº¥º¢º¢ªÅªÅ º▓ªüªéªÇºÁªçº░\",\"en\":\"Bilateral meeting\"}},{\"url\":\"uploads\\/img_20260723_065555_4a328ed7.jpg\",\"title\":{\"uz\":\"Yakuniy matbuot anjumani\",\"ru\":\"ºİªéº¥º│º¥º▓º░ªÅ º┐ªÇºÁªüªü-º║º¥º¢ªäºÁªÇºÁº¢ªåº©ªÅ\",\"en\":\"Closing press conference\"}}]','uploads/img_20260723_065506_21b6d8f8.jpg','','','',5),
