('ms77c6x5smxa','album','','{\"uz\":\"Dunay instituti_12.06.2025\",\"ru\":\"ºöªâº¢º░º╣ªüº║º©º╣ º©º¢ªüªéº©ªéªâªé_12.06.2025\",\"en\":\"Danube Institute_12.06.2025\"}','2026-07-30','[{\"url\":\"uploads\\/img_20260723_065607_198af91b.jpg\",\"title\":{\"uz\":\"Delegatsiyani kutib olish\",\"ru\":\"ºÆªüªéªÇºÁªçº░ º┤ºÁº╗ºÁº│º░ªåº©º©\",\"en\":\"Welcoming the delegation\"}},{\"url\":\"uploads\\/dunay-instituti-12-06-2025_20260708_133304_f39c763d.jpg\",\"title\":{\"uz\":\"Hamkorlik memorandumi\",\"ru\":\"º£ºÁº╝º¥ªÇº░º¢º┤ªâº╝ º¥ ªüº¥ªéªÇªâº┤º¢º©ªçºÁªüªéº▓ºÁ\",\"en\":\"Cooperation memorandum\"}},{\"url\":\"uploads\\/dunay-instituti-12-06-2025_20260708_134214_ed152ebc.jpg\",\"title\":{\"uz\":\"Ilmiy seminar\",\"ru\":\"ºØº░ªâªçº¢ªïº╣ ªüºÁº╝º©º¢º░ªÇ\",\"en\":\"Academic seminar\"}},{\"url\":\"uploads\\/img_20260708_140141_25f128cc.jpg\",\"title\":{\"uz\":\"Institut kutubxonasi\",\"ru\":\"ºæº©º▒º╗º©º¥ªéºÁº║º░ º©º¢ªüªéº©ªéªâªéº░\",\"en\":\"Institute library\"}},{\"url\":\"uploads\\/img_20260713_070438_f6dd33cd.jpg\",\"title\":{\"uz\":\"Yakuniy suhbat\",\"ru\":\"ºùº░º║º╗ªÄªçº©ªéºÁº╗ªîº¢º░ªÅ º▒ºÁªüºÁº┤º░\",\"en\":\"Closing conversation\"}}]','uploads/img_20260723_065607_198af91b.jpg','','','',10),
('ms78soh1aya8','video','https://youtu.be/vwrSEl9zeLw?si=Ap95z4Y7L0UixkHc','{\"uz\":\"O\'zbekiston-Yevropa ittifoqi: hamkorlikning yangi ufqlari. XMATM\",\"ru\":\"ºúºÀº▒ºÁº║º©ªüªéº░º¢ ÔÇô ºòº▓ªÇº¥º┐ºÁº╣ªüº║º©º╣ ªüº¥ªÄºÀ: º¢º¥º▓ªïºÁ º│º¥ªÇº©ºÀº¥º¢ªéªï ªüº¥ªéªÇªâº┤º¢º©ªçºÁªüªéº▓º░. XMATM\",\"en\":\"Uzbekistan ÔÇô European Union: new horizons of cooperation. XMATM\"}','2026-07-30',NULL,'uploads/img_20260727_085220_50d7d42b.jpg','','','uploads/video-muqova_20260824_013734_972f4d4c.jpg',14),
