('ms79abeh9lfa','album','','{\"uz\":\"Intervyu_Yaponiya\",\"ru\":\"ºİº¢ªéºÁªÇº▓ªîªÄ_º»º┐º¥º¢º©ªÅ\",\"en\":\"Interview_Japan\"}','2026-07-30','[{\"url\":\"uploads\\/img_20260727_081053_cbc0ee5f.jpg\",\"title\":{\"uz\":\"Intervyuga tayyorgarlik\",\"ru\":\"ºşº¥º┤º│º¥ªéº¥º▓º║º░ º║ º©º¢ªéºÁªÇº▓ªîªÄ\",\"en\":\"Interview preparation\"}},{\"url\":\"uploads\\/img_20260727_082122_d3648ec0.jpg\",\"title\":{\"uz\":\"Studiyada suhbat\",\"ru\":\"ºæºÁªüºÁº┤º░ º▓ ªüªéªâº┤º©º©\",\"en\":\"Studio conversation\"}},{\"url\":\"uploads\\/img_20260727_083248_04e9276a.jpg\",\"title\":{\"uz\":\"Ekspert sharhi\",\"ru\":\"ºÜº¥º╝º╝ºÁº¢ªéº░ªÇº©º╣ ªıº║ªüº┐ºÁªÇªéº░\",\"en\":\"Expert commentary\"}},{\"url\":\"uploads\\/img_20260727_083521_c98afb9b.jpg\",\"title\":{\"uz\":\"Savol-javob qismi\",\"ru\":\"ºíºÁªüªüº©ªÅ º▓º¥º┐ªÇº¥ªüº¥º▓ º© º¥ªéº▓ºÁªéº¥º▓\",\"en\":\"Q&A session\"}},{\"url\":\"uploads\\/img_20260727_083958_1d903869.jpg\",\"title\":{\"uz\":\"Yakuniy kadr\",\"ru\":\"ºñº©º¢º░º╗ªîº¢ªïº╣ º║º░º┤ªÇ\",\"en\":\"Final shot\"}}]','uploads/img_20260727_081053_cbc0ee5f.jpg','','','',16);
