INSERT INTO `pages` (`id`, `title`, `slug`, `body`, `status`, `seq`) VALUES ('14elbtemsgcdafq3eyb','{\"uz\":\"Tashqi siyosiy tadqiqotlar va xalqaro tashabbuslar markazi\",\"ru\":\"\",\"en\":\"\"}','biz-kimmiz','{\"uz\":\"<p><b>Tashqi siyosiy tadqiqotlar va xalqaro tashabbuslar markazi (TSTM) OÔÇİzbekiston Respublikasi tashqi siyosati, xalqaro siyosiy va iqtisodiy munosabatlarning dolzarb masalalari boÔÇİyicha kompleks ilmiy-tadqiqot va tahliliy faoliyatni amalga oshiruvchi davlat ilmiy-tadqiqot va tahliliy markazi hisoblanadi.<\\/b><\\/p><p><b>Markaz OÔÇİzbekiston Respublikasi Tashqi ishlar vazirligining asosiy tahliliy va ekspertlik tuzilmalaridan biri sifatida tashqi siyosatning siyosiy, xalqaro, iqtisodiy va strategik yoÔÇİnalishlarida tadqiqotlar olib boradi. Markaz tomonidan tayyorlanadigan tahliliy va ekspertlik materiallari mamlakat tashqi siyosatining ustuvor yoÔÇİnalishlarini belgilash, strategik vazifalarini shakllantirish hamda ularni amalga oshirish jarayonlarini ilmiy-tahliliy jihatdan qoÔÇİllab-quvvatlashga xizmat qiladi.<\\/b><\\/p><p><b>TSTM faoliyatining ustuvor yoÔÇİnalishlaridan biri OÔÇİzbekiston Respublikasining asosiy tashqi siyosiy hamkorlari bilan ikki tomonlama munosabatlar va amaliy hamkorlikning holati hamda istiqbollarini oÔÇİrganishdan iborat. Shu bilan birga, Markaz global va mintaqaviy miqyosda yuz berayotgan muhim siyosiy, iqtisodiy va geosiyosiy jarayonlarni muntazam ravishda tahlil qiladi hamda ularning OÔÇİzbekiston Respublikasi tashqi siyosati va milliy manfaatlariga ehtimoliy taÔÇÖsirini oÔÇİrganadi.<\\/b><\\/p><p><b>Markaz xalqaro va mintaqaviy masalalar boÔÇİyicha ekspertlik muloqotini rivojlantirish, ilmiy-amaliy konferensiyalar, davra suhbatlari, seminarlar va boshqa xalqaro ekspertlik tadbirlarini tashkil etish hamda oÔÇİtkazishda faol ishtirok etadi.<\\/b><\\/p><p><b>TSTM xalqaro munosabatlar, mintaqaviy jarayonlar va xavfsizlikning dolzarb masalalarini tadqiq etishga ixtisoslashgan xorijiy tahliliy va ilmiy-tadqiqot markazlari bilan muntazam ekspertlik muloqotlarini yoÔÇİlga qoÔÇİyish, ilmiy-tadqiqot va tahliliy loyihalarni birgalikda amalga oshirish, oÔÇİzaro tajriba almashish hamda xalqaro munosabatlarning dolzarb masalalari yuzasidan qoÔÇİshma ekspertlik tashabbuslarini ilgari surish uchun ochiq va tayyor.<\\/b><\\/p>\",\"ru\":\"\",\"en\":\"\"}','published',13);
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
